func NewSSEWriter(w http.ResponseWriter) (*SSEWriter, error) {
	if !cast.Is[http.Flusher](w) {
		return nil, errors.New("streaming not supported: ResponseWriter does not implement http.Flusher")
	}
	flusher := w.(http.Flusher)
	w.Header().Set("Content-Type", "text/event-stream")
	w.Header().Set("Cache-Control", "no-cache")
	w.Header().Set("Connection", "keep-alive")
	w.Header().Set("X-Accel-Buffering", "no")
	flusher.Flush()
	return &SSEWriter{w: w, flusher: flusher}, nil
}

// Send sends an event with an event name and data payload, then flushes.
// If event is empty, the "event: " line is omitted.
func (s *SSEWriter) Send(event string, data string) error {
	return writeSSE(s.w, s.flusher, "", event, data)
}

// SendWithID sends an event with an event ID, event name, and data payload, then flushes.
func (s *SSEWriter) SendWithID(id string, event string, data string) error {
	return writeSSE(s.w, s.flusher, id, event, data)
}

// SendJSON marshals value to JSON and sends it as an SSE event with the given event name.
func (s *SSEWriter) SendJSON(event string, value any) error {
	data, err_16 := json.String(value)
	if err_16 != nil {
		return err_16
	}
	return s.Send(event, data)
}

// Comment sends an SSE comment (": <comment>\n\n"), often used for keepalive pings.
func (s *SSEWriter) Comment(comment string) error {
	b := strings.Builder{}
	for _, line := range kukistring.Split(comment, "\n") {
		line = kukistring.TrimRight(line, "\r")
		_, _ = b.WriteString(": ")
		_, _ = b.WriteString(line)
		_, _ = b.WriteString("\n")
	}
	_, _ = b.WriteString("\n")
	_, err_17 := io.WriteString(s.w, b.String())
	if err_17 != nil {
		return err_17
	}
	s.flusher.Flush()
	return nil
}

// WriteSSE writes a single SSE event to w and flushes if w implements http.Flusher.
// Multi-line data strings are split and formatted with "data: " per line.
func WriteSSE(w io.Writer, event string, data string) error {
	return writeSSE(w, nil, "", event, data)
}

// WriteSSEWithID writes a single SSE event with an ID to w and flushes if w implements http.Flusher.
func WriteSSEWithID(w io.Writer, id string, event string, data string) error {
	return writeSSE(w, nil, id, event, data)
}

// writeSSE formats and writes an SSE event block to w.
func writeSSE(w io.Writer, flusher http.Flusher, id string, event string, data string) error {
	b := strings.Builder{}
	if id != "" {
		_, _ = b.WriteString("id: ")
		_, _ = b.WriteString(id)
		_, _ = b.WriteString("\n")
	}
	if event != "" {
		_, _ = b.WriteString("event: ")
		_, _ = b.WriteString(event)
		_, _ = b.WriteString("\n")
	}
	for _, line := range kukistring.Split(data, "\n") {
		line = kukistring.TrimRight(line, "\r")
		_, _ = b.WriteString("data: ")
		_, _ = b.WriteString(line)
		_, _ = b.WriteString("\n")
	}
	_, _ = b.WriteString("\n")
	_, err_18 := io.WriteString(w, b.String())
	if err_18 != nil {
		return err_18
	}
	if flusher != nil {
		flusher.Flush()
	} else if f, _isOk := w.(http.Flusher); _isOk {
		f.Flush()
	}
	return nil
}

// ReadSSE reads an SSE event stream from r, calling onEvent for each parsed event.
// If onEvent returns false, reading stops and ReadSSE returns empty.
// Lines starting with ':' are treated as comments and ignored.
func ReadSSE(r io.Reader, onEvent func(SSEEvent) bool) error {
	scanner := bufio.NewScanner(r)
	scanner.Buffer([]byte{}, 1048576)
	currEvent := ""
	currData := ""
	currID := ""
	hasData := false
	for scanner.Scan() {
		line := scanner.Text()
		line = kukistring.TrimRight(line, "\r")
		if line == "" {
			if hasData || currEvent != "" || currID != "" {
				evt := SSEEvent{Event: currEvent, Data: currData, ID: currID}
				if !onEvent(evt) {
					return nil
				}
				currEvent = ""
				currData = ""
				currID = ""
				hasData = false
			}
			continue
		}
		if kukistring.HasPrefix(line, ":") {
			continue
		}
		if line == "data" {
			if !hasData {
				currData = ""
				hasData = true
			} else {
				currData = fmt.Sprintf("%v\n", currData)
			}
		} else if kukistring.HasPrefix(line, "data:") {
			chunk := kukistring.TrimPrefix(line, "data:")
			if kukistring.HasPrefix(chunk, " ") {
				chunk = kukistring.TrimPrefix(chunk, " ")
			}
			if !hasData {
				currData = chunk
				hasData = true
			} else {
				currData = fmt.Sprintf("%v\n%v", currData, chunk)
			}
		} else if kukistring.HasPrefix(line, "event:") {
			currEvent = kukistring.TrimSpace(kukistring.TrimPrefix(line, "event:"))
		} else if kukistring.HasPrefix(line, "id:") {
			currID = kukistring.TrimSpace(kukistring.TrimPrefix(line, "id:"))
		}
	}
	err := scanner.Err()
	if err != nil {
		return err
	}
	if hasData || currEvent != "" || currID != "" {
		evt := SSEEvent{Event: currEvent, Data: currData, ID: currID}
		onEvent(evt)
	}
	return nil
}
